// C-25 point 1 (FR-66, 12.9, 10.3 «فحوص النموذج»): which of the six templates (Q-03) the project needs, from its
// facts, its inventory and its last results — never from a general list — with the reason that made the condition
// hold («14 ملف منطق بلا اختبارات») and the inputs the instruction will carry. An input AYAR cannot find is shown
// «ناقص: {المعلومة}» and the instruction is not generated by an assumption. A template whose condition does not hold
// is listed folded, with why. Pure: the service reads the rows and hands them over.
import type { AiTemplate, Catalog } from '@ayar/catalog';
import type { AiNeedInput, Fact, Reason } from '@ayar/protocol';
import { untestedUnits } from '@ayar/analyzers';

export interface NeedsInput {
  catalog: Catalog;
  facts: readonly Fact[];
  /** The project's files (the latest state), relative paths. */
  files: readonly string[];
  /** The profile's declared audience, when any. */
  audience: string | null;
  /** The last finished run: outcomes by check id, and the findings that matter here. */
  lastRun: { outcomes: Map<string, string>; findings: { checkId: string; ruleId: string; path: string | null; line: number | null; message: string }[] } | null;
  /** Inputs the user supplied (12.9 «ناقص: {المعلومة}» with its field), by template then key. */
  userInputs: ReadonlyMap<string, ReadonlyMap<string, string>>;
}

export interface ComputedNeed {
  template: AiTemplate;
  applies: boolean;
  reasons: Reason[];
  notApplicableReason: Reason | null;
  inputs: AiNeedInput[];
  files: string[];
  /** A digest of the facts the condition and the inputs were read from («قديم» when it changes, 12.9 point 6). */
  factsKey: string;
}

const LOGIC = /\.(js|jsx|mjs|cjs|ts|tsx|mts|cts|py)$/;
const UI_FILE = /\.(svelte|vue|jsx|tsx|html|css|scss)$|(^|\/)(components?|views?|pages?|ui)\//;
const README = /(^|\/)readme(\.[a-z]+)?$/i;
const DOCS = /^docs?\/.*\.(md|html)$|(^|\/)(openapi|swagger)\.(json|ya?ml)$|\.(stories|spec)\.[cm]?[jt]sx?$/;
const LOCALE_FILE = /(^|\/)(_locales|locales?|i18n|lang|translations?)\/.*\.(json|ya?ml|po|arb)$|\.(ar|en|fr|de)\.json$/;
const RTL = /^(ar|fa|he|ur|ps|ku|yi|dv|sd|ug)(-|_|$)/i;
const MAX_LIST = 60;

const obj = (v: unknown): Record<string, unknown> => (v !== null && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : {});
const list = (files: readonly string[]) => files.slice(0, MAX_LIST).join('\n') + (files.length > MAX_LIST ? `\n… +${files.length - MAX_LIST}` : '');
const strings = (v: unknown): string[] => (Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string') : []);

export function computeNeeds(i: NeedsInput): ComputedNeed[] {
  const facts = i.facts;
  const has = (key: string) => facts.some((f) => f.key === key);
  const values = (key: string) => facts.filter((f) => f.key === key).map((f) => obj(f.value));
  const files = i.files.filter((f) => !f.includes('/node_modules/') && !f.startsWith('node_modules/'));
  const logicFiles = files.filter((f) => LOGIC.test(f) && !UI_FILE.test(f) && !/\.(test|spec)\.|(^|\/)test_|_test\.py$|\.d\.ts$|\.config\./.test(f));
  const gaps = untestedUnits(files).map((g) => g.file);
  const testFiles = files.filter((f) => /\.(test|spec)\.[cm]?[jt]sx?$|(^|\/)(test_[^/]*|[^/]*_test)\.py$/.test(f));
  const readme = files.find((f) => README.test(f)) ?? null;
  const docs = files.filter((f) => DOCS.test(f));
  const str = (v: unknown): string => (typeof v === 'string' ? v : '');
  const scripts = values('node.script').map((s) => `${str(s.name)}: ${str(s.text).slice(0, 200)}`);
  const locales = files.filter((f) => LOCALE_FILE.test(f));
  const rtl = has('ui.rtl') || values('ui.locales').some((l) => strings(l.languages).some((x) => RTL.test(x))) || values('ui.languages').some((l) => strings(l.languages).some((x) => RTL.test(x)));
  const policy = values('references.permissionsPolicy').map((p) => str(p.path)).filter(Boolean);
  const manifest = values('references.manifest').map((p) => (typeof p.path === 'string' ? p.path : null)).filter((p): p is string => p !== null);
  const entryPages = values('ui.entryPages').flatMap((p) => strings(p.files));
  const entryFiles = [...entryPages, ...files.filter((f) => /(^|\/)(src\/)?(index|main|app|server|background|content|popup|options)\.[cm]?[jt]sx?$/.test(f))].slice(0, 30);
  const permFindings = (i.lastRun?.findings ?? []).filter((f) => f.checkId === 'sec.ext.permissions');
  const complex = (i.lastRun?.findings ?? []).filter((f) => f.checkId === 'code.complexity' && f.ruleId.startsWith('complexity.'));
  const unitOutcome = i.lastRun?.outcomes.get('beh.unit') ?? null;
  const components = new Set(files.map((f) => f.split('/')[0]!).filter((d) => !d.includes('.')));
  const topDirs = [...components].sort();

  const out: ComputedNeed[] = [];
  for (const template of i.catalog.aiTemplates) {
    const user = i.userInputs.get(template.id) ?? new Map<string, string>();
    const reasons: Reason[] = [];
    let applies = false;
    let notApplicable: Reason | null = null;
    const found = new Map<string, string>();
    let named: string[] = [];
    switch (template.id) {
      case 'ai.logic-review': {
        // «شيفرة منطق مع beh.unit ناقص أو تغطية ضعيفة في الجرد»: logic files, and no tests (or none of its own).
        const noTests = unitOutcome === 'missing' || (unitOutcome === null && testFiles.length === 0);
        applies = logicFiles.length > 0 && (noTests || gaps.length > 0);
        if (applies) reasons.push(noTests ? { key: 'aichecks.reason.logicNoTests', params: { files: logicFiles.length } } : { key: 'aichecks.reason.logicGaps', params: { files: gaps.length } });
        else notApplicable = { key: logicFiles.length ? 'aichecks.notApplicable.testsCover' : 'aichecks.notApplicable.noLogic' };
        named = noTests ? logicFiles : gaps;
        if (named.length) found.set('logicFiles', list(named));
        if (readme) found.set('expectedBehavior', readme);
        break;
      }
      case 'ai.threat-review': {
        const publicAudience = i.audience === 'public';
        const broad = permFindings.length > 0;
        const ext = has('type.browserExtension');
        applies = publicAudience || broad || (ext && policy.length > 0);
        if (publicAudience) reasons.push({ key: 'aichecks.reason.publicAudience' });
        if (broad) reasons.push({ key: 'aichecks.reason.broadPermissions', params: { count: permFindings.length } });
        if (!publicAudience && !broad && ext && policy.length) reasons.push({ key: 'aichecks.reason.extensionWithPolicy' });
        if (!applies) notApplicable = { key: 'aichecks.notApplicable.noThreatSurface' };
        if (policy.length) found.set('permissionsPolicy', policy.join('\n'));
        if (manifest.length) found.set('manifest', manifest.join('\n'));
        if (entryFiles.length) found.set('entryPoints', list(entryFiles));
        named = [...policy, ...manifest, ...entryFiles];
        break;
      }
      case 'ai.docs-consistency': {
        applies = readme !== null && scripts.length > 0;
        if (applies) reasons.push({ key: 'aichecks.reason.readmeAndScripts', params: { scripts: scripts.length } });
        else notApplicable = { key: readme ? 'aichecks.notApplicable.noScripts' : 'aichecks.notApplicable.noReadme' };
        if (readme) found.set('readme', readme);
        if (scripts.length) found.set('scripts', scripts.slice(0, MAX_LIST).join('\n'));
        named = readme ? [readme, ...docs.slice(0, 20)] : [];
        break;
      }
      case 'ai.ui-copy': {
        applies = rtl && locales.length > 0;
        if (applies) reasons.push({ key: 'aichecks.reason.rtlTexts', params: { files: locales.length } });
        else notApplicable = { key: rtl ? 'aichecks.notApplicable.noTextFiles' : 'aichecks.notApplicable.noRtl' };
        if (locales.length) found.set('textFiles', list(locales));
        named = locales;
        break;
      }
      case 'ai.test-gaps': {
        applies = testFiles.length > 0 && (readme !== null || docs.length > 0);
        if (applies) reasons.push({ key: 'aichecks.reason.testsAndSpecs', params: { tests: testFiles.length, specs: docs.length + (readme ? 1 : 0) } });
        else notApplicable = { key: testFiles.length ? 'aichecks.notApplicable.noSpecs' : 'aichecks.notApplicable.noTests' };
        if (testFiles.length) found.set('testFiles', list(testFiles));
        const specs = [...(readme ? [readme] : []), ...docs];
        if (specs.length) found.set('specs', list(specs));
        named = [...testFiles.slice(0, 30), ...specs.slice(0, 20)];
        break;
      }
      case 'ai.structure-review': {
        applies = complex.length > 0 || components.size >= 5;
        if (complex.length) reasons.push({ key: 'aichecks.reason.complexFunctions', params: { count: complex.length } });
        else if (components.size >= 5) reasons.push({ key: 'aichecks.reason.manyComponents', params: { count: components.size } });
        else notApplicable = { key: 'aichecks.notApplicable.noStructureSignal' };
        if (complex.length) found.set('complexFunctions', complex.slice(0, MAX_LIST).map((c) => `${c.path ?? '?'}${c.line ? `:${c.line}` : ''} — ${c.message.slice(0, 120)}`).join('\n'));
        if (topDirs.length) found.set('fileMap', topDirs.map((d) => `${d}/ (${files.filter((f) => f.startsWith(`${d}/`)).length})`).join('\n'));
        named = complex.map((c) => c.path).filter((p): p is string => p !== null);
        break;
      }
      default:
        notApplicable = { key: 'aichecks.notApplicable.unknownTemplate' };
    }
    const inputs: AiNeedInput[] = template.inputs.map((inp) => {
      const fromUser = user.get(inp.key);
      const fromFacts = found.get(inp.key);
      const value = fromUser ?? fromFacts ?? null;
      return { key: inp.key, labelKey: inp.label, source: fromUser !== undefined ? 'user' : fromFacts !== undefined ? (inp.from === 'user' ? 'discovery' : inp.from) : null, value: value?.slice(0, 10_000) ?? null };
    });
    const factsKey = JSON.stringify({ applies, reasons, inputs: inputs.filter((x) => x.source !== 'user').map((x) => [x.key, x.value]) });
    out.push({ template, applies, reasons, notApplicableReason: notApplicable, inputs, files: [...new Set(named)].slice(0, 200), factsKey });
  }
  return out;
}
